func test_starrocks_TestStarrocks_test_ignore_respect_nulls(self *Case, a Args) Value {
	var func_ Value
	_ = []Value{func_}
	for _, item_ := range Iter(NewTuple("FIRST_VALUE", "LAST_VALUE", "LAG", "LEAD")) {
		func_ = item_
		self.SubTest(func() {
			self.Do(425, func() { self.ValidateIdentity(F("SELECT ", FV{V: func_}, "(x IGNORE NULLS) OVER (ORDER BY t)")) })
		}, Kw("func", func_))
	}
	for _, item_ := range Iter(NewTuple("LAG", "LEAD")) {
		func_ = item_
		self.SubTest(func() {
			self.Do(429, func() { self.ValidateIdentity(F("SELECT ", FV{V: func_}, "(x IGNORE NULLS, 2) OVER (ORDER BY t)")) })
			self.Do(430, func() { self.ValidateIdentity(F("SELECT ", FV{V: func_}, "(x IGNORE NULLS, 2, 0) OVER (ORDER BY t)")) })
		}, Kw("func", func_))
	}
	self.L(433).ValidateIdentity("SELECT LAG(x, 1, 0) IGNORE NULLS OVER (ORDER BY t)", "SELECT LAG(x IGNORE NULLS, 1, 0) OVER (ORDER BY t)")
	self.L(437).ValidateAll("SELECT LEAD(x IGNORE NULLS, 1, 0) OVER (ORDER BY t)", Kw("read", NewDict("duckdb", "SELECT LEAD(x, 1, 0 IGNORE NULLS) OVER (ORDER BY t NULLS FIRST)")))
	self.L(441).ValidateAll("SELECT LAST_VALUE(x IGNORE NULLS) OVER (ORDER BY t)", Kw("read", NewDict("bigquery", "SELECT LAST_VALUE(x IGNORE NULLS) OVER (ORDER BY t)")))
	self.L(447).ValidateAll("SELECT LAST_VALUE(x) OVER (ORDER BY t)", Kw("read", NewDict("bigquery", "SELECT LAST_VALUE(x RESPECT NULLS) OVER (ORDER BY t)")))
	return nil
}

